import { describe, expect, it } from 'vitest';
import artifactTypes from '@/contracts/artifact-types.json';
import {
  ARTIFACT_RENDERERS,
  ARTIFACT_TYPES_WITHOUT_INLINE_CARD,
  INLINE_ARTIFACT_MAP,
  INLINE_ARTIFACT_TOOLS,
} from '../artifactRegistry';

/**
 * The gap this closes: the renderer table used to be two hand-written maps, and
 * a new artifact type whose card was not registered rendered as a blank block
 * in the transcript with no error anywhere. Now the backend publishes the set
 * of discriminators it can emit (`web/src/contracts/artifact-types.json`,
 * generated by `scripts/contracts/export_schemas.py` and guarded against
 * Pydantic by `tests/unit/contracts`), and this test fails when one of them has
 * neither a renderer nor a recorded decision to go without.
 */
describe('artifact id coverage', () => {
  it('has a renderer or an explicit opt-out for every type the backend emits', () => {
    const handled = new Set([
      ...ARTIFACT_RENDERERS.map((entry) => entry.artifactType),
      ...Object.keys(ARTIFACT_TYPES_WITHOUT_INLINE_CARD),
    ]);

    const unhandled = artifactTypes.artifact_types.filter((type) => !handled.has(type));
    expect(
      unhandled,
      `${unhandled.join(', ')} — add a card to artifactRegistry.ts, or record why it has none`,
    ).toEqual([]);
  });

  it('does not keep an opt-out for something that now has a card', () => {
    // A stale opt-out is how a deliberate omission silently outlives its
    // reason: the type gains a card, the entry stays, and nobody notices.
    const registered = new Set(ARTIFACT_RENDERERS.map((entry) => entry.artifactType));
    const stale = Object.keys(ARTIFACT_TYPES_WITHOUT_INLINE_CARD).filter((type) =>
      registered.has(type),
    );
    expect(stale).toEqual([]);
  });

  it('requires every opt-out to carry a reason', () => {
    for (const [type, reason] of Object.entries(ARTIFACT_TYPES_WITHOUT_INLINE_CARD)) {
      expect(reason.length, `${type} has no written reason`).toBeGreaterThan(10);
    }
  });
});

describe('the renderer table', () => {
  it('derives both lookups from one place', () => {
    // Guards the actual point of the refactor: a card added to the table must
    // appear in both, with no second edit.
    expect(Object.keys(INLINE_ARTIFACT_MAP).sort()).toEqual(
      ARTIFACT_RENDERERS.map((entry) => entry.artifactType).sort(),
    );
    expect([...INLINE_ARTIFACT_TOOLS].sort()).toEqual(
      ARTIFACT_RENDERERS.flatMap((entry) => entry.tools).sort(),
    );
  });

  it('gives every renderer a component and at least one tool', () => {
    for (const entry of ARTIFACT_RENDERERS) {
      expect(entry.component, `${entry.artifactType} has no component`).toBeDefined();
      expect(entry.tools.length, `${entry.artifactType} names no tool`).toBeGreaterThan(0);
    }
  });

  it('has no duplicate artifact type or tool', () => {
    const types = ARTIFACT_RENDERERS.map((entry) => entry.artifactType);
    expect(new Set(types).size).toBe(types.length);

    const tools = ARTIFACT_RENDERERS.flatMap((entry) => entry.tools);
    expect(new Set(tools).size).toBe(tools.length);
  });
});
